// Edit these values. Any OpenAI-compatible endpoint works (OpenAI, Groq, OpenRouter, Together, local Ollama /v1).
const CONFIG = {
  baseUrl: 'https://api.openai.com/v1',
  model: 'gpt-4o-mini',
  maxReplyWords: 80,
  // Phrases the bot must never send on its own (they go to the owner instead)
  blockedPhrases: ['refund', 'compensation', 'lawsuit', 'legal', 'free meal', 'discount code'],
  escalateAtOrBelowRating: 2,
};
return [{ json: { ...$input.first().json, config: CONFIG }, pairedItem: 0 }];

const b = $json.body || $json;
const errors = [];
if (!b.review || String(b.review).trim().length < 3) errors.push('review is required');
if (b.rating !== undefined && (isNaN(Number(b.rating)) || Number(b.rating) < 1 || Number(b.rating) > 5)) errors.push('rating must be 1-5');
return [{ pairedItem: 0, json: {
  config: $json.config,
  valid: errors.length === 0, errors,
  review: { business: b.business || 'our business', platform: b.platform || 'Google', author: b.author || 'there',
            rating: b.rating !== undefined ? Number(b.rating) : null, text: String(b.review || '').trim(), policy: b.policy || 'n/a', id: b.id || null }
} }];

const r = $json.review, c = $json.config;
return [{ pairedItem: 0, json: { config: c, review: r,
  system: `You manage online reputation for a small business. Classify the review and draft a warm, specific, brand-safe public reply of at most ${c.maxReplyWords} words. Mention one concrete detail from the review. Never admit legal liability, never promise refunds or compensation, never ask for private details publicly. Return JSON: {sentiment:'positive'|'neutral'|'negative', rating_guess:number, topics:string[], reply:string, needs_owner_attention:boolean, reason:string}.`,
  user: `Business: ${r.business}
Platform: ${r.platform}
Reviewer: ${r.author}
Star rating: ${r.rating ?? 'unknown'}
Owner policy: ${r.policy}
Review: ${r.text}` } }];

const prev = $('Build Prompt').first().json;
const c = prev.config, r = prev.review;
let out; try { out = JSON.parse($json.choices?.[0]?.message?.content || '{}'); } catch (e) { out = { reply: '', needs_owner_attention: true, reason: 'LLM returned non-JSON' }; }
const reply = String(out.reply || '');
const words = reply.split(/\s+/).filter(Boolean).length;
const hits = c.blockedPhrases.filter(p => reply.toLowerCase().includes(p));
const flags = [];
if (!reply) flags.push('empty reply');
if (words > c.maxReplyWords * 1.25) flags.push(`reply too long (${words} words)`);
if (hits.length) flags.push('blocked phrases: ' + hits.join(', '));
const rating = r.rating ?? out.rating_guess;
if (rating && rating <= c.escalateAtOrBelowRating) flags.push(`low rating (${rating})`);
if (out.needs_owner_attention) flags.push('model flagged: ' + (out.reason || 'needs attention'));
return [{ pairedItem: 0, json: { review: r, sentiment: out.sentiment || 'unknown', topics: out.topics || [], reply, flags, escalate: flags.length > 0 } }];

